        "desc": "公元前60年，西汉于乌垒城设立西域都护府，正式将西域纳入中央管辖体系。都护府统辖天山南北三十六国（后增至五十余国），罢废匈奴僮仆都尉，确立汉朝在西域的宗主地位。都护不仅掌军事、理民政，更协调诸国纷争、督察丝绸之路商道，派驻屯田吏卒保障粮饷供给。宣帝至元帝年间，匈奴日逐王降汉，西域北道尽归都护；呼韩邪单于归附后，匈奴对西域威胁大减。此后历任都护如郑吉、甘延寿、段会宗等苦心经营，西域大体安定，汉之号令行于帕米尔以东。至王莽篡汉前，西域都护府维持近七十年，中原丝绸、铁器、农耕技术西传，西域葡萄、苜蓿、良马东来，东西经济文化交流空前繁荣，为后世历代中央政权经略西域奠定了制度与疆域基础。",
        "quote": "都护西域，以安诸国",
        "quoteAuthor": "—— 《汉书·西域传》",
        "periodBg": "公元前60年西汉设立西域都护府，治乌垒城，统辖西域诸国，匈奴僮仆都尉就此罢废。初期匈奴仍存残余威胁，西域城邦林立，内部时有纷争。汉朝派驻官吏、驻军屯田，协调各国矛盾，保障丝路畅通。此后匈奴内乱，呼韩邪单于归汉，西域外部压力大为缓解。经数任都护经营，西域局势大体安定，中央政令推行于天山南北。直至王莽乱政前夕，西域大体维持归附局面，中原与西域经济文化往来持续兴盛。",
