        "name": "1500年南美洲形势图",
        "era": "世界历史",
        "path": "maps/world/south_america_1500.webp",
        "span": "1500年",
        "count": "多个",
        "desc": "1500年，欧洲殖民者刚刚抵达南美洲海岸，印加帝国在安第斯山脉崛起，阿兹特克文明在中美洲繁荣，亚马逊雨林中分布着众多原住民部落。南美洲大部分地区仍处于前殖民时代的原住民统治之下，欧洲的影响刚刚开始。",
        "quote": "黄金之国，神秘大陆",
        "quoteAuthor": "—— 欧洲探险家对南美洲的称谓",
        "periodBg": "1500年的南美洲，是原住民文明的最后辉煌时期。印加帝国在安第斯山脉建立了庞大的帝国，从今天的哥伦比亚南部延伸到智利中部，拥有高度发达的道路系统、农业技术和行政管理体系。印加人没有文字，但使用结绳记事（奇普）记录信息。在亚马逊盆地，数百个不同的部落各自为政，保持着独特的文化和生活方式。加勒比海沿岸和巴西海岸则分布着阿拉瓦克人、图皮人等族群。1500年，葡萄牙航海家佩德罗·阿尔瓦雷斯·卡布拉尔抵达巴西海岸，标志着欧洲殖民时代的开始。然而，此时欧洲人的影响仍然局限于沿海少数据点，南美洲内陆广大地区仍由原住民控制，他们的文明将在接下来的几十年中面临毁灭性的冲击。",
