        "path": "maps/world/south_america_1600.webp",
        "span": "1600年",
        "count": "多个",
        "desc": "1600年，西班牙和葡萄牙已深入南美洲内陆，印加帝国灭亡，殖民统治体系初步建立。波托西银矿成为世界最大的银矿产地，殖民经济以矿产开采和种植园为主，原住民人口因疾病和剥削急剧下降。",
        "quote": "波托西，世界的宝库",
        "quoteAuthor": "—— 西班牙殖民者",
        "periodBg": "1600年的南美洲，殖民统治已全面展开。1533年皮萨罗征服印加帝国，1572年最后一个印加抵抗据点比尔卡班巴陷落。西班牙在安第斯山区建立了以波托西银矿为核心的殖民经济体系，这座世界海拔最高的城市一度成为世界上最大的城市之一，其白银产量支撑了西班牙帝国的全球霸权。葡萄牙则沿着巴西海岸向内陆扩张，建立甘蔗种植园，从非洲贩运大量黑奴。殖民者推行米蒂塔制度，强迫原住民在矿山劳动。欧洲带来的天花、麻疹等疾病导致原住民人口在百年间减少了90%以上。天主教会在殖民体系中扮演重要角色，建立传教区，推行文化同化。此时的南美洲，原有的原住民文明已被摧毁，新的殖民社会结构正在形成。",
