        "name": "1836年南美洲形势图",
        "era": "世界历史",
        "path": "maps/world/south_america_1836.webp",
        "span": "1836年",
        "count": "多个",
        "desc": "1836年，南美洲独立运动基本完成，西班牙殖民统治瓦解，新兴国家如大哥伦比亚、秘鲁、智利、拉普拉塔联合省等相继建立。玻利瓦尔和圣马丁的解放事业取得重大成果，但各国边界争端和政治动荡持续。",
        "quote": "解放者的事业永垂不朽",
        "quoteAuthor": "—— 西蒙·玻利瓦尔",
        "periodBg": "1836年的南美洲，独立运动已基本完成。1810-1826年间，在玻利瓦尔、圣马丁、苏克雷等领袖的领导下，南美洲各国相继摆脱西班牙殖民统治。大哥伦比亚共和国（包括今天的哥伦比亚、委内瑞拉、厄瓜多尔和巴拿马）由玻利瓦尔建立，但内部矛盾重重。秘鲁和玻利维亚获得独立，但面临经济困境和政治不稳定。智利在独立后相对稳定，开始向南扩张。拉普拉塔联合省（后来的阿根廷）与巴西争夺乌拉圭的控制权。巴西则在1822年和平独立，建立帝国。此时南美洲的政治版图仍处于变动之中，各国边界尚未最终确定，考迪罗（军事强人）政治盛行，民主制度脆弱。经济上单一种植和矿产开采的殖民模式延续，英国资本逐渐取代西班牙成为主导外部力量。",
