        "year": "2025年",
        "name": "2025年南美洲形势图",
        "era": "世界历史",
        "path": "maps/world/south_america_2025.webp",
        "span": "2025年",
        "count": "12个",
        "desc": "2025年，南美洲由12个独立国家组成，包括巴西、阿根廷、智利、秘鲁、哥伦比亚、委内瑞拉、厄瓜多尔、玻利维亚、巴拉圭、乌拉圭、圭亚那和苏里南。巴西是面积最大、人口最多的国家，南美各国经济以农业、矿业和制造业为主，区域一体化组织南方共同市场（MERCOSUR）促进各国合作。",
        "quote": "同一个大陆，同一个梦想",
        "quoteAuthor": "—— 南美洲一体化愿景",
        "periodBg": "2025年的南美洲，由12个独立国家组成，总面积约1784万平方公里，人口超过4.3亿。巴西是面积最大（851万平方公里）和人口最多（约2.15亿）的国家，是金砖国家成员和重要新兴经济体。阿根廷拥有广阔的潘帕斯草原，是世界重要的粮食和牛肉出口国。智利是南美洲最稳定的经济体之一，铜矿资源丰富。秘鲁和玻利维亚拥有丰富的矿产和天然气资源。哥伦比亚在和平进程后致力于经济重建。委内瑞拉面临严重的经济和政治危机。厄瓜多尔、巴拉圭、乌拉圭等国各有特色。圭亚那和苏里南是南美洲唯二以英语和荷兰语为官方语言的国家。区域一体化方面，南方共同市场（MERCOSUR）和太平洋联盟等组织促进经济合作，但各国之间仍存在贸易壁垒和政治分歧。亚马逊雨林的保护、安第斯山脉的可持续发展是区域面临的共同挑战。",
