        "quoteAuthor": "——《新元史·阿里不哥传》",
        "periodBg": "1259年，蒙哥汗在攻打南宋时死于钓鱼城下，蒙古帝国突然没有了共主。忽必烈从鄂州前线赶回开平，自立为大汗，称薛禅汗，建元中统；他的弟弟阿里不哥也在和林被漠北宗王推举为大汗。兄弟俩各占一方，随即打起内战。",
