        "span": "1820年",
        "count": "1个",
        "desc": "1820年（清嘉庆二十五年），清朝东北疆域处于极盛时期的尾声。东北作为清朝的龙兴之地，实行特殊的八旗驻防与封禁政策。此时东北三省（盛京、吉林、黑龙江）的行政格局已基本定型：盛京将军辖地涵盖辽东半岛及辽河平原，是东北的政治经济中心；吉林将军辖地广袤，北抵外兴安岭，东达日本海，辖有库页岛及沿海诸岛；黑龙江将军辖地则控制着黑龙江流域及呼伦贝尔草原。清廷在东北实行柳条边封禁政策，限制汉人进入，以保护满族传统渔猎经济与皇家围场。同时，三姓、宁古塔、齐齐哈尔、瑷珲等军事重镇构成了抵御沙俄东扩的边防体系。1820年的东北，既是清朝祖宗发祥的圣地，也是帝国北疆防御的前沿，其特殊的军政体制与广袤的领土范围，展现了清王朝对这片根本重地的严密控制。",
        "quote": "龙兴之地，根本重地",
        "quoteAuthor": "—— 清太祖遗训",
        "periodBg": "1820年（清嘉庆二十五年），清朝东北疆域正处于极盛时期的尾声。东北作为清朝的龙兴之地，实行特殊的八旗驻防与封禁政策。此时东北三省（盛京、吉林、黑龙江）的行政格局已基本定型：盛京将军辖地涵盖辽东半岛及辽河平原，是东北的政治经济中心；吉林将军辖地广袤，北抵外兴安岭，东达日本海，辖有库页岛及沿海诸岛；黑龙江将军辖地则控制着黑龙江流域及呼伦贝尔草原。清廷在东北实行柳条边封禁政策，限制汉人进入，以保护满族传统渔猎经济与皇家围场。同时，三姓、宁古塔、齐齐哈尔、瑷珲等军事重镇构成了抵御沙俄东扩的边防体系。1820年的东北，既是清朝祖宗发祥的圣地，也是帝国北疆防御的前沿，其特殊的军政体制与广袤的领土范围，展现了清王朝对这片根本重地的严密控制。",
        "author": "南风",
