        "quote": "文明在迁徙中交融",
        "periodBg": "印欧人大迁徙是上古世界史上的重大事件。约公元前3000年起，生活在东欧草原的印欧人开始向四面八方迁徙：一支进入印度次大陆（创造吠陀文明），一支进入伊朗高原（成为米底人和波斯人），一支进入希腊和意大利（成为希腊人和罗马人），还有一支进入北欧和中欧。这次大迁徙深刻改变了欧亚大陆的语言、文化和民族格局。",
