        "periodBg": "罗马帝国在2世纪初达到极盛，疆域西起不列颠，东至美索不达米亚，北达莱茵河和多瑙河，南抵撒哈拉沙漠。图拉真皇帝在位时（98-117年）征服了达契亚和帕提亚，使帝国疆域达到最大。帝国境内有完善的道路网络、统一的货币和法律体系，拉丁语和希腊语通行。罗马的行政制度、建筑技术（拱券、混凝土）、工程技术（引水渠、下水道）对后世影响深远。",
