        "quote": "奥斯曼的阴影笼罩欧洲",
        "quoteAuthor": "欧洲编年史",
        "periodBg": "奥斯曼帝国是15-16世纪世界上最强大的伊斯兰帝国。1453年穆罕默德二世攻陷君士坦丁堡，灭亡拜占庭帝国。16世纪苏莱曼大帝时期，帝国疆域达到鼎盛：西至匈牙利，东至两河流域，南至埃及和阿拉伯半岛，北至高加索。奥斯曼帝国控制着东西方贸易路线，是欧洲文艺复兴时期的重要对手。帝国在行政、军事（禁卫军）、法律、建筑（清真寺）方面取得了卓越成就。",
