        "periodBg": "唐朝实行三省六部制，三省为中书省（决策）、门下省（审核）、尚书省（执行），分工明确，相互制衡。中书省位于长安城内皇城中央偏北，负责起草诏令；门下省位于中书省之东，负责审核和封驳；尚书省位于承天门南，下设六部（吏、户、礼、兵、刑、工），负责执行。三省长官共同议政于政事堂（中书门下）。三省六部制是中国古代政治制度的成熟典范，对后世影响深远。",
