        "quote": "扬帆万里，宣威海外",
        "quoteAuthor": "《明史·郑和传》",
        "periodBg": "郑和（1371-1433年）是明朝伟大的航海家。1405-1433年间，郑和奉命七次率领庞大的船队出使西洋，先后到达东南亚、印度、波斯湾、阿拉伯半岛和东非沿岸三十余国，最远到达东非的木骨都束（今索马里摩加迪沙）。郑和宝船（最大的长148米）是当时世界上最先进的船只。郑和下西洋促进了中国与亚非各国的经济文化交流，是世界航海史上的壮举。",
