        "quote": "康乾盛世，疆域极广",
        "quoteAuthor": "《清史稿》",
        "periodBg": "1820年是清嘉庆二十五年，清朝疆域达到极盛。版图包括内地十八省（直隶、江苏、安徽、山西、山东、河南、陕西、甘肃、浙江、江西、湖北、湖南、四川、福建、广东、广西、云南、贵州）和盛京、吉林、黑龙江、内蒙古、外蒙古、新疆、青海、西藏等广大地区。清政府在各地设将军、都统、办事大臣等官员管辖，形成了对边疆地区的有效治理。嘉庆末年吏治腐败，白莲教起义刚被镇压，清朝由盛转衰的迹象已经显现。",
