        "periodBg": "1840年前，中国清朝处于嘉庆道光年间，实行闭关锁国政策，仅留广州一港对外贸易。与此同时，西方世界正经历巨大变革：英国完成工业革命，法国大革命（1789年）和拿破仑战争（1799-1815年）重塑了欧洲格局，美国独立（1776年）和拉丁美洲独立运动改变了美洲版图。英国通过东印度公司控制印度，工业品生产能力远超中国。鸦片贸易成为中英矛盾的焦点，1840年鸦片战争即将爆发。",
