        "desc": "展示达·伽马、哥伦布、麦哲伦等航海家开辟的新航路，连接欧洲、非洲、美洲和亚洲。",
        "quote": "地球是圆的",
        "quoteAuthor": "麦哲伦",
        "periodBg": "15世纪末至16世纪初，欧洲航海家开辟了通往东方和美洲的新航路。迪亚士1487年到达好望角，达·伽马1498年到达印度，哥伦布1492年到达美洲，麦哲伦1519-1522年完成环球航行。新航路开辟是世界历史上划时代的事件，打破了各大陆的孤立状态，开启了全球化的进程。新航路促进了世界贸易的发展，但也带来了殖民扩张和奴隶贸易的黑暗历史。",
