        "count": "2条",
        "desc": "展示1493年教皇亚历山大六世和1494年《托尔德西里亚斯条约》划定的教皇子午线，西葡两国瓜分世界。",
        "quote": "教皇子午线分割了世界",
        "periodBg": "1492年哥伦布到达美洲后，西班牙和葡萄牙两国为争夺新发现土地发生争执。1493年教皇亚历山大六世划定教皇子午线：线西属于西班牙，线东属于葡萄牙。1494年西葡签订《托尔德西里亚斯条约》，将教皇子午线西移约800公里，大致位于亚速尔群岛以西。根据该条约，巴西东部划归葡萄牙，美洲其他地区划归西班牙。教皇子午线体现了欧洲列强瓜分世界的野心，是近代殖民扩张的起点。",
