        "desc": "展示16-17世纪继新航路开辟之后，欧洲航海家探索北冰洋、太平洋和澳大利亚周边的新航线。",
        "quote": "探索未知，开拓新世界",
        "quoteAuthor": "航海家语录",
        "periodBg": "新航路开辟后，欧洲航海家继续探索未知海域。16世纪，西班牙和葡萄牙船队探索了太平洋岛屿和东南亚群岛。17世纪，荷兰船队（如塔斯曼）探索了澳大利亚和新西兰海岸，发现了塔斯马尼亚岛和新西兰南岛。英国航海家（如德雷克）完成了环球航行，探索了北美西海岸。俄国探险家穿越西伯利亚，到达太平洋沿岸。这些探索活动极大地扩展了人类对地球的认知，为近代地理学和航海技术发展奠定了基础。",
