        "quote": "海上马车夫",
        "quoteAuthor": "形容荷兰",
        "periodBg": "荷兰在17世纪成为海上马车夫，建立了庞大的殖民帝国。荷兰东印度公司（1602年）和西印度公司（1621年）负责海外扩张。在亚洲，荷兰占领了锡兰（今斯里兰卡）、印度尼西亚群岛、台湾（1624-1662年）和南非好望角；在美洲，建立了新尼德兰（今纽约）和荷属圭亚那（今苏里南）；在非洲，占领了黄金海岸（今加纳）和安哥拉。荷兰还是大西洋三角贸易的重要参与者。",
