        "desc": "展示19世纪初拉丁美洲独立运动胜利后新兴国家的版图，包括墨西哥、大哥伦比亚、秘鲁、智利、阿根廷、巴西等。",
        "quote": "解放者的事业永垂不朽",
        "quoteAuthor": "西蒙·玻利瓦尔",
        "periodBg": "19世纪初，拉丁美洲独立运动席卷整个大陆。1810-1826年间，在玻利瓦尔、圣马丁、苏克雷等领袖的领导下，西属美洲各国相继独立。墨西哥（1810-1821年）、大哥伦比亚（1819-1831年，包括今天哥伦比亚、委内瑞拉、厄瓜多尔）、秘鲁（1821年）、玻利维亚（1825年）、智利（1818年）、拉普拉塔联合省（1816年，后来的阿根廷）获得独立。巴西则在1822年和平独立，建立帝国。独立后的拉丁美洲面临政局动荡、边界争端和经济落后的挑战，但摆脱了殖民枷锁，开启了新的发展道路。",
