        "quote": "北美是欧洲的粮仓",
        "quoteAuthor": "殖民时期谚语",
        "periodBg": "17-18世纪，英国在北美东海岸建立了十三个殖民地，分为三类：新英格兰殖民地（马萨诸塞、罗得岛、康涅狄格、新罕布什尔）以谷物、木材和渔业为主；中部殖民地（纽约、新泽西、宾夕法尼亚、特拉华）以谷物和商业为主；南方殖民地（马里兰、弗吉尼亚、北卡罗来纳、南卡罗来纳、佐治亚）以烟草、稻米和靛蓝种植为主，大量使用黑奴劳动力。农作物分布差异导致了南北社会经济的深刻分歧，为后来的美国内战埋下伏笔。",
