        "quote": "俄国需要出海口",
        "quoteAuthor": "彼得大帝",
        "periodBg": "16-18世纪初，俄国从一个莫斯科周边的内陆公国迅速扩张为领土面积最大的国家。伊凡四世（雷帝）时期，俄国东扩至乌拉尔山脉，征服了喀山汗国和阿斯特拉罕汗国（1552-1556年）。17世纪，俄国探险家穿越西伯利亚，到达太平洋沿岸（1639年），并征服了东西伯利亚。18世纪初，彼得大帝进行了北方战争（1700-1721年），从瑞典手中夺得波罗的海出海口，建立了圣彼得堡。俄国通过不断扩张，奠定了广阔的领土基础。",
