        "desc": "展示19世纪末20世纪初西方列强在亚洲的殖民地和势力范围，包括英属印度、法属印度支那、荷属东印度等。",
        "quote": "亚洲被列强瓜分殆尽",
        "quoteAuthor": "时人评论",
        "periodBg": "19世纪末20世纪初，亚洲大部分地区沦为西方列强的殖民地或势力范围。英国拥有印度（1858年成为英属印度）、缅甸、马来亚、新加坡，并在中国长江流域有势力范围。法国拥有印度支那（越南、老挝、柬埔寨），并在中国西南有势力范围。荷兰拥有荷属东印度（印度尼西亚）。美国在1898年美西战争后获得菲律宾，并提出门户开放政策。日本在甲午战争（1894-1895年）后获得台湾，在日俄战争（1904-1905年）后在中国东北拥有势力范围。亚洲面临被彻底瓜分的危机。",
