        "desc": "展示19世纪末柏林会议后欧洲列强瓜分非洲的殖民格局，非洲大陆几乎被英、法、德、比、葡、意、西完全分割。",
        "quote": "非洲是欧洲列强的地图",
        "periodBg": "1884-1885年的柏林会议正式开启了列强瓜分非洲的进程。到20世纪初，非洲大陆几乎被欧洲列强完全瓜分。英国拥有从埃及到南非的开普敦至开罗殖民地带（包括埃及、苏丹、东非、南非），以及西非部分。法国拥有西非（塞内加尔、象牙海岸、法属苏丹等）、北非（阿尔及利亚、突尼斯、摩洛哥）、赤道非洲（刚果、加蓬等）。比利时拥有刚果自由邦（后为比属刚果）。德国拥有喀麦隆、多哥、西南非洲（纳米比亚）、东非（坦噶尼喀）。葡萄牙拥有安哥拉和莫桑比克。非洲传统国家和社会结构遭到摧毁。",
