        "desc": "展示太平天国运动的兴起、发展和失败过程，从金田起义到定都天京，再到天京陷落的主要战役路线。",
        "quote": "有田同耕，有饭同食，有钱同使，无处不均匀",
        "quoteAuthor": "《天朝田亩制度》",
        "periodBg": "太平天国运动（1851-1864年）是中国近代史上规模最大的农民起义。1851年洪秀全在广西金田起义，1853年攻占南京改名天京，定都于此。太平天国颁布《天朝田亩制度》，提出有田同耕的理想，但未能实现。1856年天京事变后内部矛盾激化，军事形势逆转。曾国藩领导的湘军逐步反攻，1864年天京陷落，太平天国运动失败。该运动沉重打击了清王朝统治，加速了晚清政治军事格局的变化。",
