        "desc": "展示甲午战争后帝国主义列强在中国划分的势力范围和租借地，德国占胶州湾，俄国租旅顺大连，英国租威海卫。",
        "quote": "瓜分豆剖",
        "quoteAuthor": "康有为",
        "periodBg": "甲午战争后，列强掀起瓜分中国的狂潮。1897年德国强占胶州湾，1898年俄国租借旅顺和大连（后来被日本继承），英国租借威海卫（1898年）和九龙新界（1898年），法国租借广州湾（1899年），日本割占台湾（1895年）并将福建划为势力范围。列强还在中国设立各种特权，控制海关、盐税和铁路权益。中国面临被彻底瓜分的危机，民族意识空前觉醒，推动了戊戌变法（1898年）和义和团运动（1900年）的发生。",
