        "quote": "四万万同胞，热血洒神州",
        "quoteAuthor": "义和团民谣",
        "periodBg": "1900年，义和团运动以扶清灭洋为口号在华北迅速蔓延，围攻东交民巷外国使馆和西什库教堂。清廷向十一国宣战，但八国联军（英、美、法、德、俄、日、意、奥）迅速攻陷大沽炮台（6月）、天津（7月）和北京（8月），慈禧太后携光绪帝西逃西安。1901年签订《辛丑条约》，赔款四亿五千万两白银，拆除大沽炮台，允许外国驻军，划定东交民巷为使馆界。中国完全沦为半殖民地半封建社会。",
