        "periodBg": "1911年10月10日，武昌起义爆发，打响了辛亥革命第一枪。湖北军政府成立后，各省纷纷响应：湖南（10月22日）、陕西（10月22日）、江西（10月23日）、山西（10月29日）、云南（10月30日）、贵州（11月4日）、浙江（11月5日）、江苏（11月5日）、安徽（11月8日）、广西（11月9日）、福建（11月9日）、山东（11月13日）、广东（11月14日）、四川（11月27日）相继宣告独立。1912年1月1日，中华民国临时政府在南京成立，孙中山就任临时大总统，清朝统治覆灭。",
