        "quote": "城头变幻大王旗",
        "quoteAuthor": "鲁迅",
        "periodBg": "1916年袁世凯称帝失败去世，北洋军阀集团迅速分裂。段祺瑞的皖系控制安徽、浙江、福建、陕西等省，是中央政府的主要掌控者（1916-1920年）。冯国璋、曹锟的直系控制直隶、江苏、湖北、江西等省。张作霖的奉系控制东北三省。此外还有晋系阎锡山（山西）、桂系陆荣廷（广西）、滇系唐继尧（云南）、川军各派（四川）等。军阀之间混战不断，中央政权名存实亡，中国陷入严重分裂状态。",
