        "desc": "展示国民革命军北伐的主要进军路线，从广东出发，先后攻克湖南、湖北、江西、福建、浙江、江苏，最终占领北京。",
        "quote": "打倒列强除军阀",
        "quoteAuthor": "《国民革命歌》",
        "periodBg": "1926年7月，国民革命军在广州誓师北伐，目标是消灭北洋军阀。北伐军分三路进军：西路（主力）沿粤汉铁路北上，攻克汀泗桥、贺胜桥，10月占领武昌；中路攻江西，11月占领南昌；东路攻福建、浙江，1927年3月占领上海和南京。1927年4月蒋介石发动四一二政变，国共分裂。1928年，国民党继续北伐，张作霖退往关外，皇姑屯被炸死。张学良东北易帜，北伐基本完成。",
