        "quote": "星星之火，可以燎原",
        "quoteAuthor": "毛泽东",
        "periodBg": "国共分裂后，中国共产党转入农村开展武装斗争。1927年10月毛泽东率秋收起义部队上井冈山，创建第一个农村革命根据地。此后各地革命根据地相继建立：中央苏区（江西、福建，1931年）、鄂豫皖苏区（湖北、河南、安徽）、湘赣苏区（湖南、江西）、湘鄂西苏区（湖南、湖北）、闽浙赣苏区（福建、浙江、江西）、左右江苏区（广西）、海陆丰苏区（广东）。1931年11月，中华苏维埃共和国在江西瑞金成立。1930-1931年，国民党发动三次围剿，均被红军粉碎。",
