        "quote": "红军不怕远征难，万水千山只等闲",
        "quoteAuthor": "毛泽东《七律·长征》",
        "periodBg": "1934年10月，中央红军（红一方面军）约八万六千人从江西瑞金出发开始长征。长征途中经历了突破四道封锁线、血战湘江、遵义会议（1935年1月）、四渡赤水、巧渡金沙江、强渡大渡河、飞夺泸定桥、翻越雪山（夹金山）、穿越草地（松潘草地）等艰难历程。1935年10月，红一方面军到达陕北吴起镇，与陕北红军会师。红二、四方面军也于1936年10月在甘肃会宁会师。长征行程约二万五千里，是中国革命史上的壮丽史诗。",
