        "periodBg": "1937年7月7日夜，日军在北平（今北京）西南的卢沟桥附近进行军事演习，借口一名士兵失踪，要求进入宛平县城搜查，遭中国守军拒绝。日军随即向卢沟桥和宛平城发起进攻，中国守军第29军奋起抵抗。卢沟桥事变标志着日本全面侵华战争的开始，也标志着中国全民族抗战的爆发。7月29日北平沦陷，7月30日天津沦陷，华北局势急剧恶化。",
