        "desc": "展示台儿庄战役的战场态势和双方攻防布局，中国军队在台儿庄取得了抗战以来的重大胜利。",
        "quote": "台儿庄大捷，振奋全国人心",
        "quoteAuthor": "李宗仁",
        "periodBg": "台儿庄战役（1938年3-4月）是徐州会战的重要组成部分。日军第5、第10师团企图从山东南下进攻徐州，中国第五战区司令长官李宗仁指挥约29万兵力迎战。3月24日，日军猛攻台儿庄，中国守军池峰城部与日军展开惨烈的巷战。4月初，孙连仲、汤恩伯部形成合围，歼灭日军约一万二千人，取得抗战以来正面战场的首次重大胜利。台儿庄大捷极大鼓舞了全国军民的抗战信心，打破了日军不可战胜的神话。",
