        "quote": "抗战胜利，举国欢庆",
        "quoteAuthor": "时人记载",
        "periodBg": "1945年8月15日，日本宣布无条件投降，中国人民抗日战争取得伟大胜利。战后，国民党军队占据西南、华中、华南大部地区；八路军、新四军控制华北、华中和东北部分农村地区及中小城镇。苏联红军出兵东北后，中共部队迅速进入东北，控制了北满和南满部分地区。美国以扶蒋反共政策支持蒋介石，大量美械装备武装国民党军队。国共双方围绕接收日军投降、军队整编和政治协商等问题激烈博弈，内战一触即发。",
