        "quote": "钟山风雨起苍黄，百万雄师过大江",
        "quoteAuthor": "毛泽东《七律·人民解放军占领南京》",
        "periodBg": "三大战役是人民解放军在1948年9月至1949年1月间进行的战略决战。辽沈战役（1948年9-11月）在东北进行，歼灭国民党军四十七万余人，东北全境解放。淮海战役（1948年11-1949年1月）在苏北地区进行，歼灭国民党军五十五万余人，解放了长江以北的华东和中原地区。平津战役（1948年11-1949年1月）在华北进行，歼灭和改编国民党军五十二万余人，北平和平解放。三大战役共歼灭国民党军主力一百五十余万人，为解放全中国奠定了基础。",
