        "periodBg": "1949年4月20日，国民党政府拒绝在《国内和平协定》上签字。4月21日，毛泽东、朱德发布《向全国进军的命令》，人民解放军百万雄师在西起九江、东至江阴的五百余公里战线上强渡长江。4月23日，第三野战军占领南京，宣告国民党在大陆统治的覆灭。5月3日解放杭州，5月27日解放上海。渡江战役歼敌四十三万余人，解放了华东和江南广大地区，加速了全国解放的进程。",
