        "quote": "战后欧洲的版图被重新绘制",
        "periodBg": "第一次世界大战（1914-1918年）彻底改变了欧洲的政治版图。战前欧洲有德意志帝国、奥匈帝国、奥斯曼帝国、俄罗斯帝国等四大帝国。战后，德国沦为魏玛共和国，领土被削减；奥匈帝国解体为奥地利、匈牙利、捷克斯洛伐克、南斯拉夫等多个国家；奥斯曼帝国被肢解，土耳其仅保留小亚细亚；俄罗斯帝国在十月革命后变为苏联，但丧失了波兰、芬兰、波罗的海诸国。凡尔赛体系（1919年）重建了欧洲格局，但埋下了二战的隐患。",
