        "quote": "战争导火索随时可能点燃",
        "periodBg": "一战前，欧洲形成了两大军事集团的对峙。三国同盟（1882年由德、奥、意建立）以德国为核心，是同盟国阵营的基础。三国协约（1907年由英、法、俄建立）以英国为核心，是协约国阵营的基础。两大集团在巴尔干、非洲、亚洲等殖民地问题上矛盾尖锐。军备竞赛不断升级，德国建造了强大的海军挑战英国的海上霸权。萨拉热窝事件（1914年6月28日）成为战争爆发的导火索，两大集团迅速卷入全面战争。",
