        "quote": "西线无战事——一切都是战事",
        "quoteAuthor": "雷马克",
        "periodBg": "一战欧洲战场分为三条主要战线。西线（法比边境至瑞士）是主要战场，从1914年马恩河战役后陷入堑壕战僵局，凡尔登战役（1916年）和索姆河战役（1916年）成为绞肉机。东线（波罗的海至黑海）以机动作战为主，俄军与德奥军队多次攻防，1917年俄国十月革命后退出一战。南线（巴尔干半岛）是次要战场，塞尔维亚、希腊等国与保加利亚、土耳其作战。此外还有意大利战线、中东战线等。",
