        "quote": "凡尔赛体系埋下了二战的种子",
        "periodBg": "一战后，战胜国通过凡尔赛和约（1919年）及其系列和约重新划分了欧洲和中东版图。德国丧失阿尔萨斯-洛林、波兰走廊等，并被限制军队规模。奥匈帝国解体为奥地利、匈牙利、捷克斯洛伐克和南斯拉夫。奥斯曼帝国被肢解，中东地区被划分给英法两国委任统治：英国获得伊拉克、外约旦、巴勒斯坦；法国获得叙利亚和黎巴嫩。意大利获得阜姆等地。凡尔赛体系对德国过于苛刻，导致德国民族复仇情绪高涨，成为二战的远因。",
