        "quote": "资本输出是帝国主义的核心特征",
        "quoteAuthor": "列宁《帝国主义是资本主义的最高阶段》",
        "periodBg": "一战前，资本输出是帝国主义列强的重要特征。英国是最大的资本输出国，到1914年海外投资达四十亿英镑，主要投向美洲、印度、非洲和澳大利亚。法国是第二大资本输出国，海外投资约三百五十亿法郎，主要投向俄国、土耳其和南欧。德国是第三大资本输出国，海外投资约二百二十亿马克，主要投向欧洲和拉丁美洲。资本输出不仅获取高额利润，也是列强控制殖民地、扩大势力范围的重要手段。",
