        "periodBg": "1933年希特勒上台后，德国开始重整军备。1936年进军莱茵兰非军事区。1938年3月吞并奥地利（德奥合并）。1938年9月慕尼黑会议后，德国吞并捷克斯洛伐克的苏台德地区。1939年3月，德国完全占领捷克斯洛伐克。1939年8月，德国与苏联签订《苏德互不侵犯条约》（莫洛托夫-里宾特洛甫条约），划分了在波兰的势力范围。1939年9月1日，德国入侵波兰，第二次世界大战全面爆发。",
