        "quote": "波兰再次被从地图上抹去又恢复",
        "periodBg": "二战中波兰遭受了惨重损失。战后，波兰的东部领土（西白俄罗斯、西乌克兰）划归苏联，但波兰从德国获得了奥得-尼斯河以东的领土（包括西里西亚、波美拉尼亚和东普鲁士南部）。波兰的领土整体向西移动了约两百公里，面积比战前略有缩小。这一变更导致约八百万德国人被强制迁出，波兰人从东部迁入新领土。波兰版图的西移是雅尔塔体系的重要组成部分，影响了战后欧洲的格局。",
