        "periodBg": "二战后，在苏联影响下形成了庞大的社会主义阵营。欧洲包括：苏联、波兰、捷克斯洛伐克、匈牙利、罗马尼亚、保加利亚、阿尔巴尼亚、东德（1949年）、南斯拉夫（与苏联关系紧张）。亚洲包括：中国（1949年）、蒙古、朝鲜（1948年）、越南（1954年后）。美洲包括：古巴（1961年）。社会主义阵营在冷战时期与西方资本主义阵营尖锐对立。1956年匈牙利事件、1968年布拉格之春表明阵营内部矛盾。1991年苏联解体后，社会主义阵营瓦解。",
