        "quote": "冷战是意识形态的战争",
        "periodBg": "冷战时期，北约和华约两大军事集团在欧洲形成尖锐对峙。北约（1949年成立）以美国为首，包括美国、加拿大、英国、法国、意大利、西德（1955年）等十六个国家，总部设在布鲁塞尔。华约（1955年成立）以苏联为首，包括苏联、波兰、捷克斯洛伐克、匈牙利、罗马尼亚、保加利亚、东德、阿尔巴尼亚（1968年退出）。中欧、德国和柏林是两大集团对峙的最前线。双方在欧洲部署了大量常规部队和核武器，形成了恐怖平衡。1991年华约解散，冷战结束。",
