        "quote": "苏联的解体是20世纪最大的地缘政治事件",
        "periodBg": "1990-1991年，苏联加速解体。1990年3月11日，立陶宛率先宣布独立。随后，爱沙尼亚（1991年8月20日）、拉脱维亚（1991年8月21日）、乌克兰（1991年8月24日）、白俄罗斯（1991年8月25日）、摩尔多瓦（1991年8月27日）等相继独立。1991年12月8日，俄罗斯、乌克兰、白俄罗斯三国签署《别洛韦日协议》，宣布苏联解体。12月16日，哈萨克斯坦最后宣布独立。1991年12月25日，戈尔巴乔夫辞去苏联总统职务，苏联正式解体，形成十五个独立国家。",
