        "span": "1994年",
        "count": "1条",
        "desc": "展示英法海底隧道的路线和结构示意图，连接英国多佛和法国加莱，是世界上最长的海底铁路隧道。",
        "quote": "穿越英吉利海峡的大工程",
        "quoteAuthor": "工程界评价",
        "periodBg": "英法海底隧道（英吉利海峡隧道）是连接英国和法国的铁路隧道，1994年5月6日开通运营。隧道全长50.5公里，其中海底部分长37.9公里，位于英吉利海峡海床以下约75米，是世界上最长的海底隧道。隧道由三条平行隧道组成：两条铁路单线隧道（供火车运行）和一条服务隧道（用于通风、维护和紧急疏散）。隧道每年运送旅客超过二千万人次，极大地促进了英法两国之间的人员和货物往来，是欧洲一体化和工程技术的标志性成就。",
